["import re\n\nwith open('connector-manager.ts', 'r') as f:\n    content = f.read()\n\n# Fix the array constructor typo\ncontent = content.replace(\n    'wp && Array[0]',\n    'wp && wp[0]'\n)\n\n# Fix the IVec type\ncontent = content.replace(\n    '[wp[0] + connector.x, wp[1] + connector.y] as IVec',\n    'new PointLocation([wp[0] + connector.x, wp[1] + connector.y])'\n)\n\nwith open('connector-manager.ts', 'w') as f:\n    f.write(content)\n\nprint('Fixed!')"]